-- Vantara synthetic Snowflake loader
-- Profile: tiny
-- Execute locally with Snowflake credentials; not run in Cloud agents.
-- Unique-id generator columns use VARCHAR. Table stages are @DB.SCHEMA.%TABLE.
-- Prefer: uv run aide demo load-snowflake --profile tiny
-- CREATE DATABASE/SCHEMA are optional; the Python loader does not require those grants.
CREATE DATABASE IF NOT EXISTS VANTARA_RAW;
USE DATABASE VANTARA_RAW;
CREATE SCHEMA IF NOT EXISTS CRM;
CREATE SCHEMA IF NOT EXISTS BILLING;
CREATE SCHEMA IF NOT EXISTS PAYMENTS;
CREATE SCHEMA IF NOT EXISTS PRODUCT;
CREATE SCHEMA IF NOT EXISTS SUPPORT;
CREATE OR REPLACE TABLE CRM.ACCOUNTS (ACCOUNT_ID VARCHAR, ACCOUNT_NAME VARCHAR, WEBSITE_DOMAIN VARCHAR, INDUSTRY VARCHAR, COUNTRY VARCHAR, OWNER_ID VARCHAR, CREATED_AT TIMESTAMP_TZ, UPDATED_AT TIMESTAMP_TZ, IS_DELETED BOOLEAN, _LOADED_AT TIMESTAMP_TZ, _EXTRACT_DATE DATE, _SOURCE_FILE VARCHAR);
PUT file://fixtures/tiny/v2/csv/crm/accounts.csv @VANTARA_RAW.CRM.%ACCOUNTS AUTO_COMPRESS=FALSE OVERWRITE=TRUE;
COPY INTO CRM.ACCOUNTS FROM @VANTARA_RAW.CRM.%ACCOUNTS FILE_FORMAT=(TYPE=CSV SKIP_HEADER=1 FIELD_OPTIONALLY_ENCLOSED_BY='"' EMPTY_FIELD_AS_NULL=TRUE TRIM_SPACE=TRUE DATE_FORMAT='YYYY-MM-DD' TIMESTAMP_FORMAT='YYYY-MM-DD"T"HH24:MI:SSTZH:TZM') ON_ERROR='ABORT_STATEMENT';

CREATE OR REPLACE TABLE CRM.CONTACTS (CONTACT_ID VARCHAR, ACCOUNT_ID VARCHAR, FIRST_NAME VARCHAR, LAST_NAME VARCHAR, EMAIL VARCHAR, PHONE VARCHAR, CREATED_AT TIMESTAMP_TZ, UPDATED_AT TIMESTAMP_TZ, _LOADED_AT TIMESTAMP_TZ, _EXTRACT_DATE DATE, _SOURCE_FILE VARCHAR);
PUT file://fixtures/tiny/v2/csv/crm/contacts.csv @VANTARA_RAW.CRM.%CONTACTS AUTO_COMPRESS=FALSE OVERWRITE=TRUE;
COPY INTO CRM.CONTACTS FROM @VANTARA_RAW.CRM.%CONTACTS FILE_FORMAT=(TYPE=CSV SKIP_HEADER=1 FIELD_OPTIONALLY_ENCLOSED_BY='"' EMPTY_FIELD_AS_NULL=TRUE TRIM_SPACE=TRUE DATE_FORMAT='YYYY-MM-DD' TIMESTAMP_FORMAT='YYYY-MM-DD"T"HH24:MI:SSTZH:TZM') ON_ERROR='ABORT_STATEMENT';

CREATE OR REPLACE TABLE CRM.OPPORTUNITIES (OPPORTUNITY_ID VARCHAR, ACCOUNT_ID VARCHAR, STAGE VARCHAR, AMOUNT NUMBER(18,2), CREATED_AT TIMESTAMP_TZ, UPDATED_AT TIMESTAMP_TZ, _LOADED_AT TIMESTAMP_TZ, _EXTRACT_DATE DATE, _SOURCE_FILE VARCHAR);
PUT file://fixtures/tiny/v2/csv/crm/opportunities.csv @VANTARA_RAW.CRM.%OPPORTUNITIES AUTO_COMPRESS=FALSE OVERWRITE=TRUE;
COPY INTO CRM.OPPORTUNITIES FROM @VANTARA_RAW.CRM.%OPPORTUNITIES FILE_FORMAT=(TYPE=CSV SKIP_HEADER=1 FIELD_OPTIONALLY_ENCLOSED_BY='"' EMPTY_FIELD_AS_NULL=TRUE TRIM_SPACE=TRUE DATE_FORMAT='YYYY-MM-DD' TIMESTAMP_FORMAT='YYYY-MM-DD"T"HH24:MI:SSTZH:TZM') ON_ERROR='ABORT_STATEMENT';

CREATE OR REPLACE TABLE CRM.ACCOUNT_CROSSWALK (ACCOUNT_ID VARCHAR, BILLING_CUSTOMER_ID INTEGER, CREATED_AT TIMESTAMP_TZ, _LOADED_AT TIMESTAMP_TZ, _EXTRACT_DATE DATE, _SOURCE_FILE VARCHAR);
