COPY INTO CRM.ACCOUNT_CROSSWALK FROM @VANTARA_RAW.CRM.%ACCOUNT_CROSSWALK FILE_FORMAT=(TYPE=CSV SKIP_HEADER=1 FIELD_OPTIONALLY_ENCLOSED_BY='"' EMPTY_FIELD_AS_NULL=TRUE TRIM_SPACE=TRUE DATE_FORMAT='YYYY-MM-DD' TIMESTAMP_FORMAT='YYYY-MM-DD"T"HH24:MI:SSTZH:TZM') ON_ERROR='ABORT_STATEMENT';

